87	    parser.setApplicationDescription(qlibrevnaApp->applicationName());
88	    parser.addHelpOption();
89	    parser.addVersionOption();
90	    parser.addOption(QCommandLineOption({"p","port"}, "Specify port to listen for SCPI commands", "port"));
91	    parser.addOption(QCommandLineOption({"d","device"}, "Only allow connections to the specified device", "device"));
92	    parser.addOption(QCommandLineOption("no-gui", "Disables the graphical interface"));
93	    parser.addOption(QCommandLineOption("cal", "Calibration file to load on startup", "cal"));
94	    parser.addOption(QCommandLineOption("setup", "Setup file to load on startup", "setup"));
95	    parser.addOption(QCommandLineOption("reset-preferences", "Resets all preferences to their default values"));
96	
97	    parser.process(QCoreApplication::arguments());
98	
99	    if(parser.isSet("reset-preferences")) {
100	        Preferences::getInstance().setDefault();
101	    } else {
102	        Preferences::getInstance().load();
103	    }
104	
105	    auto &p = Preferences::getInstance();
106	
107	    device = nullptr;
108	//    vdevice = nullptr;
109	    modeHandler = nullptr;
110	
111	    if(parser.isSet("port")) {
112	        bool OK;
113	        auto port = parser.value("port").toUInt(&OK);
114	        if(!OK) {
115	            // set default port
116	            port = Preferences::getInstance().SCPIServer.port;
117	        }
118	        StartTCPServer(port);
119	        p.manualTCPport();
120	    } else if(p.SCPIServer.enabled) {
121	        StartTCPServer(p.SCPIServer.port);
122	    }
