129	    }
130	    if(p.StreamingServers.VNADeembeddedData.enabled) {
131	        streamVNADeembeddedData = new StreamingServer(p.StreamingServers.VNADeembeddedData.port);
132	    }
133	    if(p.StreamingServers.SARawData.enabled) {
134	        streamSARawData = new StreamingServer(p.StreamingServers.SARawData.port);
135	    }
136	    if(p.StreamingServers.SANormalizedData.enabled) {
137	        streamSANormalizedData = new StreamingServer(p.StreamingServers.SANormalizedData.port);
138	    }
