270	void AppWindow::closeEvent(QCloseEvent *event)
271	{
272	    auto& pref = Preferences::getInstance();
273	    if(pref.Startup.UseSetupFile && pref.Startup.AutosaveSetupFile) {
274	        SaveSetup(pref.Startup.SetupFile);
275	    }
276	    modeHandler->shutdown();
277	    QSettings settings;
278	    settings.setValue("geometry", saveGeometry());
279	    // deactivate currently used mode (stores mode state in settings)
280	    if(modeHandler->getActiveMode()) {
281	        modeHandler->deactivate(modeHandler->getActiveMode());
282	    }
283	    if(device) {
284	        device->disconnectDevice();
285	        device = nullptr;
286	    }
287	    delete modeHandler;
288	    modeHandler = nullptr;
289	    pref.store();
290	    for(auto driver : DeviceDriver::getDrivers()) {
291	        delete driver;
292	    }
293	    QMainWindow::closeEvent(event);
294	}
