299	
300	    auto& pref = Preferences::getInstance();
301	    if(pref.Startup.UseSetupFile) {
302	        LoadSetup(pref.Startup.SetupFile);
303	    } else {
304	        auto vnaIndex = modeHandler->createMode("Vector Network Analyzer", Mode::Type::VNA);
305	        modeHandler->createMode("Signal Generator", Mode::Type::SG);
306	        modeHandler->createMode("Spectrum Analyzer", Mode::Type::SA);
307	        modeHandler->setCurrentIndex(vnaIndex);
308	    }
309	}
